use hy_check::{check_file, Verdict};
use hy_syntax::parse_file;
fn codes(src: &str) -> Vec<String> {
    check_file(&parse_file("test.hy", src).expect("parse")).diagnostics.into_iter().map(|d| d.code).collect()
}
fn assert_accept(src: &str) {
    let r = check_file(&parse_file("test.hy", src).expect("parse"));
    assert_eq!(r.verdict, Verdict::Accept, "expected Accept, got {:?}", r.diagnostics);
}
#[test]
fn nested_closure_o8_slot_loan_and_reassign_alias_a3_1403() {
    let src_reject = "struct acct { bal int }\nfn top_loop_o8() {\n    m := map[string]acct{\"a\": acct{bal: 1}}\n    p := &m[\"a\"]\n    for i in 0..2 {\n        _ = i\n        q := &m[\"a\"]\n        q.bal = 2\n        p.bal = p.bal + 1\n    }\n}\nfn main() {\n    m := map[string]acct{\"a\": acct{bal: 1}, \"k\": acct{bal: 1}}\n    other := map[string]acct{\"k\": acct{bal: 1}}\n    ns := []acct{acct{bal: 1}}\n    outer := fn() {\n        f := fn() {\n            p := &m[\"a\"]\n            p = &m[\"a\"]\n            q := &m[\"a\"]\n            q.bal = 10\n            p.bal = p.bal + 1\n        }\n        f()\n    }\n    f_shadow_loan := fn() {\n        p := &m[\"a\"]\n        if true {\n            p := &m[\"a\"]\n            p.bal = 10\n        }\n        p.bal = p.bal + 1\n    }\n    f1 := fn(c bool) {\n        a := m\n        if c { a = other }\n        p := &m[\"k\"]\n        a[\"z\"] = acct{bal: 2}\n        p.bal = p.bal + 1\n    }\n    f2 := fn(c bool) {\n        a := m\n        if c {\n            a := other\n            _ = a\n        }\n        p := &m[\"k\"]\n        a[\"z\"] = acct{bal: 2}\n        p.bal = p.bal + 1\n    }\n    f3_multihop := fn(n int) {\n        a := other\n        b := other\n        p := &m[\"k\"]\n        for i in 0..n {\n            _ = i\n            a = b\n            b = m\n        }\n        a[\"z\"] = acct{bal: 2}\n        p.bal = p.bal + 1\n    }\n    f4_zero_iter := fn(n int) {\n        a := m\n        p := &m[\"k\"]\n        for i in 0..n {\n            _ = i\n            a = other\n        }\n        a[\"z\"] = acct{bal: 2}\n        p.bal = p.bal + 1\n    }\n    f5_field := fn() {\n        var p *acct\n        for i in 0..2 {\n            _ = i\n            ns[0].bal = 2\n            p = &ns[0]\n        }\n        p.bal = p.bal + 1\n    }\n    f6_delete_replay := fn() {\n        var p *acct\n        for i in 0..2 {\n            _ = i\n            delete(m, \"k\")\n            p = &m[\"k\"]\n            p := 0\n            _ = p\n        }\n        p.bal = p.bal + 1\n    }\n    f7_shadow_then_alias := fn() {\n        p := &m[\"a\"]\n        if true {\n            p := 0\n            _ = p\n        }\n        r := p\n        q := &m[\"a\"]\n        q.bal = 10\n        r.bal = r.bal + 1\n    }\n    f8_18hop := fn(n int) {\n        a1, a2, a3, a4, a5, a6, a7, a8, a9, a10, a11, a12, a13, a14, a15, a16, a17, a18 := other, other, other, other, other, other, other, other, other, other, other, other, other, other, other, other, other, other\n        p := &m[\"k\"]\n        for i in 0..n {\n            _ = i\n            a1, a2, a3, a4, a5, a6, a7, a8, a9 = a2, a3, a4, a5, a6, a7, a8, a9, a10\n            a10, a11, a12, a13, a14, a15, a16, a17 = a11, a12, a13, a14, a15, a16, a17, a18\n            a18 = m\n        }\n        a1[\"z\"] = acct{bal: 2}\n        p.bal = p.bal + 1\n    }\n    x_out := m\n    y_out := m\n    f9_param_shadow := fn(m map[string]acct) {\n        p := &x_out[\"a\"]\n        y_out[\"z\"] = acct{bal: 2}\n        p.bal = p.bal + 1\n        _ = m\n    }\n    f10_escape_insert := fn(c bool) {\n        var r *acct\n        if c {\n            p := &m[\"a\"]\n            r = p\n        }\n        m[\"z\"] = acct{bal: 2}\n        r.bal = r.bal + 1\n    }\n    f11_escape_o8 := fn(c bool) {\n        var r *acct\n        if c {\n            p := &m[\"a\"]\n            r = p\n        }\n        q := &m[\"a\"]\n        q.bal = 1\n        r.bal = r.bal + 1\n    }\n    f12_carry_owner_conflict := fn(c bool) {\n        var r *acct\n        for i in 0..2 {\n            _ = i\n            if c {\n                p := &m[\"a\"]\n                p.bal = 1\n                r = p\n            }\n        }\n        r.bal = r.bal + 1\n    }\n    f13_two_aliases := fn() {\n        p := &m[\"a\"]\n        r := p\n        s := p\n        r.bal = 1\n        m[\"z\"] = acct{bal: 2}\n        s.bal = s.bal + 1\n    }\n    f14_assign_backedge := fn() {\n        var p *acct\n        p = new(acct)\n        for j in 0..2 {\n            _ = j\n            m[\"z\"] = acct{bal: 2}\n            p.bal = 1\n            p = &m[\"a\"]\n            p.bal = 2\n        }\n    }\n    f15_nested_loop := fn() {\n        for i in 0..2 {\n            _ = i\n            p := &m[\"a\"]\n            for j in 0..2 {\n                _ = j\n                p.bal = p.bal + 1\n                m[\"z\"] = acct{bal: 2}\n            }\n        }\n    }\n    f16_backedge_2hop := fn() {\n        var r *acct\n        var s *acct\n        for i in 0..2 {\n            _ = i\n            s = r\n            p := &m[\"a\"]\n            p.bal = 1\n            r = p\n        }\n        m[\"z\"] = acct{bal: 2}\n        s.bal = s.bal + 1\n    }\n    f17_shadow_copy := fn() {\n        p := &m[\"a\"]\n        if true {\n            p := p\n            m[\"z\"] = acct{bal: 2}\n            p.bal = 1\n        }\n    }\n    f18_swap := fn() {\n        var r *acct\n        s := new(acct)\n        p := &m[\"a\"]\n        r = p\n        r, s = s, r\n        m[\"z\"] = acct{bal: 2}\n        s.bal = s.bal + 1\n    }\n    f19_nested_cap := fn() {\n        p := &m[\"a\"]\n        g := fn() {\n            p.bal = 1\n        }\n        m[\"z\"] = acct{bal: 2}\n        g()\n    }\n    f20_closure_ret := fn() {\n        get := fn() map[string]acct {\n            return m\n        }\n        a := get()\n        p := &m[\"k\"]\n        a[\"z\"] = acct{bal: 2}\n        p.bal = p.bal + 1\n    }\n    f21_closure_mut := fn() {\n        g := fn() {\n            delete(m, \"a\")\n        }\n        p := &m[\"a\"]\n        g()\n        p.bal = 1\n    }\n    f22_branch_kill := fn(c bool) {\n        p := &m[\"a\"]\n        if c {\n            p = new(acct)\n        }\n        m[\"z\"] = acct{bal: 2}\n        p.bal = p.bal + 1\n    }\n    f23_loop_branch_kill := fn(c bool) {\n        var r *acct\n        r = new(acct)\n        for i in 0..2 {\n            _ = i\n            if c {\n                r = new(acct)\n            }\n            m[\"z\"] = acct{bal: 2}\n            r.bal = 1\n            r = &m[\"a\"]\n            r.bal = 2\n        }\n    }\n    p_top := &m[\"a\"]\n    r_top := p_top\n    p_top = &m[\"a\"]\n    r_top.bal = r_top.bal + 1\n    p_top.bal = p_top.bal + 1\n    outer()\n    f_shadow_loan()\n    f1(false)\n    f2(true)\n    f3_multihop(2)\n    f4_zero_iter(0)\n    f5_field()\n    f6_delete_replay()\n    f7_shadow_then_alias()\n    f8_18hop(18)\n    f9_param_shadow(other)\n    f10_escape_insert(true)\n    f11_escape_o8(true)\n    f12_carry_owner_conflict(true)\n    f13_two_aliases()\n    f14_assign_backedge()\n    f15_nested_loop()\n    f16_backedge_2hop()\n    f17_shadow_copy()\n    f18_swap()\n    f19_nested_cap()\n    f20_closure_ret()\n    f21_closure_mut()\n    f22_branch_kill(false)\n    f23_loop_branch_kill(false)\n}";
    let diags = check_file(&parse_file("test.hy", src_reject).expect("parse")).diagnostics;
    let mut lines: Vec<u32> = diags.iter().filter(|d| d.code == "HYB-E3102").map(|d| d.span.start.line).collect();
    lines.sort_unstable();
    assert_eq!(lines, vec![7, 20, 29, 38, 48, 60, 70, 77, 86, 100, 113, 120, 130, 139, 148, 160, 168, 181, 191, 195, 202, 212, 220, 229, 237, 245, 256, 264]);
    assert_eq!(lines.len(), 28);
    assert_accept("struct acct { bal int }\nfn check_loop(m map[string]acct, other map[string]acct) {\n    f := fn() {\n        a_loop := other\n        p_loop := &m[\"a\"]\n        for i in 0..2 {\n            _ = i\n            a_loop = other\n            a_loop[\"z\"] = acct{bal: 2}\n            a_loop = m\n        }\n        p_loop.bal = p_loop.bal + 1\n    }\n    f()\n}\nfn main() {\n    m := map[string]acct{\"a\": acct{bal: 1}, \"b\": acct{bal: 2}}\n    other := map[string]acct{\"x\": acct{bal: 9}}\n    ns := []acct{acct{bal: 1}, acct{bal: 2}}\n    p := 0\n    _ = p\n    a_outer := m\n    _ = a_outer\n    f := fn(c bool, a_outer map[string]acct) {\n        for i in 0..2 {\n            _ = i\n            m[\"a\"] = acct{bal: 0}\n            p := &m[\"a\"]\n            p.bal = 1\n            if c { _ = i }\n        }\n        lp := &m[\"a\"]\n        a_outer[\"b\"] = acct{bal: 9}\n        lp.bal = lp.bal + 1\n        s0 := &ns[0]\n        ns[1].bal = 50\n        s0.bal = s0.bal + 1\n        h_in := fn() {\n            _ = m\n            _ = other\n        }\n        a2 := m\n        a2 = other\n        l2 := &m[\"a\"]\n        a2[\"b\"] = acct{bal: 4}\n        other[\"b\"] = acct{bal: 4}\n        l2.bal = l2.bal + 1\n        h_in()\n        s1, s2 := fn(m map[string]acct) { _ = m }, fn(m map[string]acct) { _ = m }\n        s1(other)\n        s2(other)\n        ps := &m[\"a\"]\n        if c {\n            ps := 0\n            _ = ps\n        }\n        ps = &m[\"a\"]\n        ps.bal = ps.bal + 1\n        p_pre := &m[\"a\"]\n        p_pre.bal = 1\n        m[\"z\"] = acct{bal: 2}\n        q_pre := &m[\"a\"]\n        q_pre.bal = 2\n        if c {\n            p_pre := 0\n            _ = p_pre\n        }\n        var r_dead *acct\n        p_dead := &m[\"a\"]\n        p_dead.bal = 1\n        r_dead = p_dead\n        r_dead = new(acct)\n        s_dead := r_dead\n        m[\"z\"] = acct{bal: 2}\n        s_dead.bal = s_dead.bal + 1\n        pa := &m[\"a\"]\n        pb := &m[\"b\"]\n        pa.bal = pb.bal + 1\n        var r_sh *acct\n        r_sh = new(acct)\n        p_b := &m[\"a\"]\n        p_b.bal = 1\n        if c {\n            r_sh := p_b\n            r_sh.bal = 1\n            var r_sh2 *acct\n            r_sh2 = &m[\"a\"]\n            r_sh2.bal = 1\n            var r_sh3 *acct\n            p_b2 := &m[\"a\"]\n            r_sh3 = p_b2\n            r_sh3.bal = 1\n        }\n        m[\"z\"] = acct{bal: 2}\n        r_sh.bal = r_sh.bal + 1\n        var r_rst *acct\n        for k in 0..2 {\n            r_rst = new(acct)\n            p_rst := &m[\"a\"]\n            p_rst.bal = 1\n            r_rst = p_rst\n            _ = k\n        }\n        r_rst.bal = r_rst.bal + 1\n        for j in 0..2 {\n            if c {\n                p := &m[\"a\"]\n                p.bal = 1\n            }\n            p_sh := &m[\"a\"]\n            p_sh.bal = 1\n            if c {\n                p_sh := 0\n                m[\"z\"] = acct{bal: 2}\n                _ = p_sh\n            }\n            q_loc := &m[\"a\"]\n            q_loc = &m[\"a\"]\n            s_loc := q_loc\n            s_loc = &m[\"a\"]\n            s_loc.bal = 1\n            q2_loc := &m[\"a\"]\n            q2_loc.bal = 2\n            var r_loc *acct\n            if c {\n                p_loc := &m[\"a\"]\n                r_loc = p_loc\n            }\n            r_loc.bal = r_loc.bal + 1\n            _ = j\n        }\n    }\n    f_var_shadow := fn(c bool, r2 *acct) {\n        r := new(acct)\n        if c {\n            var r *acct\n            r = &m[\"a\"]\n            r.bal = 1\n            var r2 *acct\n            p := &m[\"a\"]\n            r2 = p\n            r2.bal = 1\n        }\n        m[\"z\"] = acct{bal: 2}\n        r.bal = r.bal + 1\n        r2.bal = r2.bal + 1\n    }\n    f_var_shadow(true, new(acct))\n    f_loop_shadow := fn(c bool) {\n        var r *acct\n        for i in 0..2 {\n            _ = i\n            r = &m[\"a\"]\n            r.bal = 1\n        }\n        m[\"z\"] = acct{bal: 2}\n        if c {\n            r := 0\n            _ = r\n        }\n    }\n    f_loop_shadow(true)\n    f(true, other)\n}");
}
